local cL=(getgenv and getgenv()) or _ENV or _G
local sL={} for i=97,122 do sL[#sL+1]=string.char(i) end
local SN={12,15,1,4,19,20,18,9,14,7}
local Qj="" for i=1,#SN do Qj=Qj..sL[SN[i]] end
local EX=cL and cL[Qj]
local CV=type(EX)=="function"
if CV then
local Cx={8,15,15,11,6,21,14,3,20,9,15,14}
local CB="" for i=1,#Cx do CB=CB..sL[Cx[i]] end
local ML={18,5,19,20,15,18,5,6,21,14,3,20,9,15,14}
local oX="" for i=1,#ML do oX=oX..sL[ML[i]] end
local eN=cL[CB]
local QP=cL[oX]
local cn=false
if type(eN)=="function" and type(QP)=="function" then
local iZ=function() return 5 end
local Wd=pcall(eN,iZ,function() return -777 end)
if Wd and iZ()==-777 then
local UL=pcall(QP,iZ)
cn=(UL and iZ()==5)
end
if not cn then pcall(QP,iZ) end
if not cn and type(cL.math)=="table" and type(cL.math.abs)=="function" then
local Yb=cL.math.abs
if Yb(5)==5 then
local yB,Cp=pcall(eN,Yb,function() return -777 end)
if yB and Yb(5)==-777 then
local wr=pcall(QP,Yb)
cn=(wr and Yb(5)==5)
if not cn then pcall(QP,Yb) cL.math.abs=(type(Cp)=="function" and Cp) or function(v) if v<0 then return -v end return v end end
end
end
end
if cn then
local Er={EX,eN,QP}
local Oh=cL.string
if type(Oh)=="table" then
Er[#Er+1]=Oh.char Er[#Er+1]=Oh.byte Er[#Er+1]=Oh.sub Er[#Er+1]=Oh.rep Er[#Er+1]=Oh.len
end
if type(cL.table)=="table" and cL.table.concat then Er[#Er+1]=cL.table.concat end
if cL.pcall then Er[#Er+1]=cL.pcall end
if type(cL.math)=="table" and cL.math.floor then Er[#Er+1]=cL.math.floor end
for Ct=1,#Er do local zt=Er[Ct] if type(zt)=="function" then pcall(QP,zt) end end
end
end
end
if not CV then return nil end

